/* Polices embarquées pour le PDF, enregistrées dans jsPDF au chargement.
 *
 * Sans elles, jsPDF retombe sur Helvetica et son encodage WinAnsi, qui perd
 * des lettres françaises courantes ici : « bœuf haché » devenait « buf haché ».
 * Ce sont les deux polices du site, réduites au latin de base et au latin
 * étendu A, puis figées à un poids donné.
 *
 *   Outfit    : SIL Open Font License 1.1, github.com/Outfitio/Outfit-Fonts
 *   Fraunces  : SIL Open Font License 1.1, github.com/undercasetype/Fraunces
 *
 * Fichier engendré ; ne pas modifier à la main.
 */
(function (API) {
  'use strict';
  var polices = [
    ['Outfit-normal.ttf', 'Outfit', 'normal',
     ''],
    ['Outfit-bold.ttf', 'Outfit', 'bold',
     ''],
    ['Fraunces-bold.ttf', 'Fraunces', 'bold',
     ''],
  ];

  polices.forEach(function (p) {
    API.addFileToVFS(p[0], p[3]);
  });

  API.events.push(['addFonts', function () {
    var doc = this;
    polices.forEach(function (p) {
      doc.addFont(p[0], p[1], p[2]);
    });
  }]);
})(window.jspdf.jsPDF.API);
